const builtinIconById = new Map([...ICON_LIBRARY, ...LEGACY_ICON_LIBRARY].map(entry => [entry.id, entry]));

/** Metadata copies for browsing and future AI selection; SVG stays behind id.
 * Invalid non-string inputs return an empty list without coercing user objects.
 * @param {string} [query] @param {string} [category]
 * @returns {{id:string,label:string,category:string,tags:string[]}[]}
 */
function listBuiltinIcons(query = '', category = '') {
  if (typeof query !== 'string' || typeof category !== 'string') return [];
  const search = query.trim().toLowerCase();
  return ICON_LIBRARY.filter(entry =>
    (!category || entry.category === category) &&
    (!search || [entry.id, entry.label, ...entry.tags].join(' ').toLowerCase().includes(search))
  ).map(({ id, label, category: group, tags }) => ({ id, label, category: group, tags: [...tags] }));
}

/** Exact canonical id lookup. Unknown, inherited and non-string names are null.
 * @param {string} id @returns {Readonly<BuiltinIcon> | null}
 */
function getBuiltinIcon(id) {
  return typeof id === 'string' ? builtinIconById.get(id) || null : null;
}

